  not = `Botón de activar el giroscopio - Clic del pad derecho`,
  rot = `La entrada del giroscopio solo se activará cuando se haga clic con el botón del trackpad derecho.`,
  iot = `Botón de activar el giroscopio - Clic del pad izquierdo`,
  aot = `La entrada del giroscopio solo se activará cuando se haga clic con el botón del trackpad izquierdo.`,
