  sot = `La entrada del giroscopio solo se activará cuando se pulse el botón superior frontal derecho.`,
  cot = `Botón de activar el giroscopio - Botón superior frontal izquierdo`,
  lot = `La entrada del giroscopio solo se activará cuando se pulse el botón superior frontal izquierdo.`,
  uot = `Botón de activar el giroscopio - Empuñadura derecha`,
