  fot = `Botón de activar el giroscopio - Empuñadura izquierda`,
  pot = `La entrada del giroscopio solo se activará cuando se pulse el botón de la empuñadura izquierda.`,
  mot = `Botón de activar el giroscopio - Pulsación completa del gatillo izquierdo`,
  hot = `La entrada del giroscopio solo se activará cuando se pulse el gatillo izquierdo..`,
  got = `Botón de activar el giroscopio - Pulsación completa del gatillo derecho`,
  _ot = `La entrada del giroscopio solo se activará cuando se pulse completamente el gatillo derecho.`,
  vot = `Botón de activar el giroscopio - Pulsación suave del gatillo izquierdo`,
  yot = `La entrada del giroscopio solo se activará cuando se pulse levemente el gatillo izquierdo.`,
  bot = `Botón de activar el giroscopio - Pulsación suave del gatillo derecho`,
  xot = `La entrada del giroscopio solo se activará cuando se pulse levemente el gatillo derecho.`,
  Sot = `Botón de activar el giroscopio - A`,
  Cot = `La entrada del giroscopio solo se activará cuando se pulse el botón A.`,
