  Tot = `La entrada del giroscopio solo se activará cuando se pulse el botón B.`,
  Eot = `Botón de activar el giroscopio - X`,
  Dot = `La entrada del giroscopio solo se activará cuando se pulse el botón X.`,
  Oot = `Botón de activar el giroscopio - Y`,
  kot = `La entrada del giroscopio solo se activará cuando se pulse el botón Y.`,
  Aot = `Botón de activar el giroscopio - Equis`,
  jot = `La entrada del giroscopio solo se activará cuando se pulse el botón Equis.`,
